// Cloudflare email decode fallback
(function(){
  try {
    var els = document.querySelectorAll('[data-cfemail]');
    for (var i = 0; i < els.length; i++) {
      var el = els[i];
      var enc = el.getAttribute('data-cfemail');
      if (enc) {
        var r = parseInt(enc.substr(0, 2), 16), email = '', n = 2;
        for (; enc.length - n; n += 2) {
          email += String.fromCharCode(parseInt(enc.substr(n, 2), 16) ^ r);
        }
        el.outerHTML = '<a href="mailto:' + email + '">' + email + '</a>';
      }
    }
  } catch(e){}
})();
